import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.LX5S0jbT.js";const m=JSON.parse('{"title":"Pi","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function s(n,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="pi" tabindex="-1">Pi <a class="header-anchor" href="#pi" aria-label="Permalink to &quot;Pi&quot;">​</a></h1><p>Pi is an extensible AI agent that works from your terminal. Give it a goal and a working folder, and it can inspect files, run commands, edit content, and work through multi-step tasks.</p><p>Use Pi for software development, research notes, writing projects, data files, or hobby work. You can use Pi as is, prompt it to adapt itself to your workflow, or build other applications powered by Pi using the SDK.</p><h2 id="start-using-pi" tabindex="-1">Start using Pi <a class="header-anchor" href="#start-using-pi" aria-label="Permalink to &quot;Start using Pi&quot;">​</a></h2><p>New to Pi? Follow the <a href="./quickstart.html">Quickstart</a> to install Pi, connect a model, and complete your first task.</p><p>If Pi is already installed, choose what you want to do:</p><ul><li><a href="./usage.html">Use Pi interactively</a> to add files, run commands, direct ongoing work, and export results.</li><li><a href="./models.html">Choose a model</a> or connect a subscription, API key, local model, or compatible endpoint.</li><li><a href="./sessions.html">Continue or branch a session</a> to resume work or explore another approach without losing history.</li><li><a href="./configuration.html">Configure Pi</a> for your preferences, working folders, instructions, and reusable resources.</li><li><a href="./how-pi-works.html">Understand how Pi works</a>, including tools, context, sessions, and the agent loop.</li></ul><h2 id="customize-pi" tabindex="-1">Customize Pi <a class="header-anchor" href="#customize-pi" aria-label="Permalink to &quot;Customize Pi&quot;">​</a></h2><p>Pi can reuse prompts, load specialized instructions, add executable integrations, change its terminal interface, connect model services, and distribute these resources as packages. Use the <a href="./quickstart.html#choose-how-to-customize-pi">Quickstart customization chooser</a> to select the smallest mechanism that meets your need.</p><h2 id="automate-or-embed-pi" tabindex="-1">Automate or embed Pi <a class="header-anchor" href="#automate-or-embed-pi" aria-label="Permalink to &quot;Automate or embed Pi&quot;">​</a></h2><ul><li>Use <a href="./cli.html#invocation-and-output">print mode</a> for one-off and scripted tasks.</li><li>Use <a href="./json.html">JSON event stream mode</a> to consume structured events from one run.</li><li>Use <a href="./rpc.html">RPC mode</a> to control a separate Pi process.</li><li>Use the <a href="./sdk.html">TypeScript SDK</a> to run Pi inside an application.</li></ul><h2 id="find-reference-and-setup-information" tabindex="-1">Find reference and setup information <a class="header-anchor" href="#find-reference-and-setup-information" aria-label="Permalink to &quot;Find reference and setup information&quot;">​</a></h2><p>Use the reference pages to look up <a href="./cli.html">CLI options</a>, <a href="./settings.html">settings</a>, <a href="./providers.html">providers</a>, <a href="./keybindings.html">keybindings</a>, and <a href="./environment-variables.html">environment variables</a>.</p><p>For platform-specific help, see <a href="./terminal-setup.html">Terminal Setup</a>, <a href="./windows.html">Windows</a>, <a href="./tmux.html">tmux</a>, <a href="./termux.html">Termux on Android</a>, or <a href="./containerization.html">Containerization</a>.</p><h2 id="work-safely" tabindex="-1">Work safely <a class="header-anchor" href="#work-safely" aria-label="Permalink to &quot;Work safely&quot;">​</a></h2><p>Pi&#39;s tools and extensions run with the permissions of the Pi process. Project trust controls which project resources Pi loads, but it does not sandbox tool calls. Review <a href="./security.html">Security</a> before using untrusted files, repositories, extensions, or unattended automation.</p>',16)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
